/**
 * Avatar renderer.
 *
 * The portrait is a static image. To "revive" it we cut out the eye and mouth
 * regions (regions come from face.json, generated by MediaPipe on the server or
 * tuned manually in Settings) and redraw those parts with transforms:
 *
 *   - blink: squash the eye region vertically
 *   - gaze:  shift the eye region inside its box
 *   - head:  rotate/translate the whole canvas
 *   - speech: scale the mouth region vertically according to the phoneme
 *             "openness" streamed by Piper, modulated by the audio level
 *
 * This is deliberately NOT photorealistic lip sync - it is a stylised, readable
 * animation. It reacts to the audio but has no per-frame mouth tracking.
 */

const BLINK_DURATION = 0.19;
const MOUTH_RANGE = 0.85;

export const EMOTIONS = {
  neutral:   { eyeY: 0, eyeScale: 1.0, mouth: 0.18, tilt: 0, blink: [3.2, 5.6] },
  listening: { eyeY: -2.5, eyeScale: 1.03, mouth: 0.24, tilt: 0, blink: [2.1, 3.4] },
  thinking:  { eyeY: -3.5, eyeScale: 1.02, mouth: 0.20, tilt: 1.0, blink: [3.0, 4.8] },
  speaking:  { eyeY: -1.5, eyeScale: 1.0, mouth: 0.28, tilt: 0.5, blink: [2.6, 4.2] },
  happy:     { eyeY: -3.5, eyeScale: 1.06, mouth: 0.32, tilt: -0.9, blink: [2.4, 3.8] },
  surprised: { eyeY: -4.5, eyeScale: 1.12, mouth: 0.45, tilt: 0, blink: [1.9, 3.0] },
  curious:   { eyeY: -2.5, eyeScale: 1.05, mouth: 0.26, tilt: 1.6, blink: [2.5, 4.0] },
  sad:       { eyeY: 1.5, eyeScale: 0.94, mouth: 0.12, tilt: -1.2, blink: [4.2, 6.4] },
  error:     { eyeY: 0, eyeScale: 0.97, mouth: 0.10, tilt: 0, blink: [3.0, 4.6] },
};

const PART_ORDER = ['right_eye', 'left_eye', 'mouth'];

/**
 * Compute the image -> canvas transform so that the face fills the canvas.
 * Shared by the avatar renderer and the region editor in Settings.
 */
export function computeTransform(face, cw, ch) {
  const aspect = cw / ch;
  const fraction = face.crop_fraction || 0.7;
  const faceH = face.face_box[3] - face.face_box[1];
  const cropH = faceH / fraction;
  const cropW = Math.max(1, cropH * aspect);
  let x0 = (face.face_box[0] + face.face_box[2]) / 2 - cropW / 2;
  let y0 = (face.face_box[1] + face.face_box[3]) / 2 - cropH / 2;
  x0 = Math.max(0, Math.min(x0, Math.max(0, face.width - cropW)));
  y0 = Math.max(0, Math.min(y0, Math.max(0, face.height - cropH)));
  const sx = cw / cropW;
  const sy = ch / cropH;
  return { sx, sy, ox: -x0 * sx, oy: -y0 * sy, crop: { x0, y0, w: cropW, h: cropH } };
}

export class Avatar {
  constructor(canvas, options = {}) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d');
    this.opts = Object.assign(
      { animations: true, idle: true, emotions: true, eyeTracking: true, getLevel: null },
      options
    );
    this.image = null;
    this.face = null;
    this.override = null;
    this.status = 'idle';
    this.emotion = 'neutral';
    this.level = 0;
    this.volume = 1;
    this.tracker = null;
    this.trackerEnabled = false;
    this.trackerFps = 0;
    this.running = false;
    this.dpr = 1;
    this.cw = 0;
    this.ch = 0;
    this.sx = 1;
    this.sy = 1;
    this.ox = 0;
    this.oy = 0;
    this.crop = { x0: 0, y0: 0, w: 1, h: 1 };
    this.t = 0;
    this.lastTs = 0;
    this.fps = 0;

    // animation state
    this.blink = { timer: 1.0, active: false, phase: 0 };
    this.gaze = { x: 0, y: 0, tx: 0, ty: 0 };
    this.head = { x: 0, y: 0, rot: 0, tx: 0, ty: 0, trot: 0 };
    this.emotionState = Object.assign({}, EMOTIONS.neutral);
    this.parts = {};
    this.speech = { frames: [], cursor: 0, start: 0, active: false };
    this.mouth = { target: 0.18, value: 0.18 };
    this.trackerSignal = null;

    for (const name of PART_ORDER) {
      this.parts[name] = { tx: 0, ty: 0, rot: 0, sx: 1, sy: 1, box: null, ibox: null };
    }

    window.addEventListener('resize', () => this.layout());
  }

  /* ------------------------------------------------------------------ loading */
  async load(imageUrl, faceUrl, override = null) {
    this.override = override;
    this.image = await loadImage(imageUrl);
    const face = await fetch(faceUrl).then((r) => r.json());
    this.face = face;
    if (this.override) {
      this.face.parts = Object.assign({}, this.face.parts, this.override);
    }
    this.layout();
    return this;
  }

  applyOverride(override) {
    this.override = override;
    if (this.face) {
      this.face.parts = Object.assign({}, this.face.parts, override || {});
      this.layout();
    }
    return this;
  }

  layout() {
    const rect = this.canvas.getBoundingClientRect();
    if (!rect.width || !rect.height) return;
    this.cw = rect.width;
    this.ch = rect.height;
    this.dpr = Math.min(2, window.devicePixelRatio || 1);
    this.canvas.width = Math.round(this.cw * this.dpr);
    this.canvas.height = Math.round(this.ch * this.dpr);
    if (!this.face) return;

    const f = this.face;
    const t = computeTransform(f, this.cw, this.ch);
    this.crop = t.crop;
    this.sx = t.sx;
    this.sy = t.sy;
    this.ox = t.ox;
    this.oy = t.oy;

    for (const name of PART_ORDER) {
      const box = f.parts && f.parts[name] ? f.parts[name].box : null;
      this.parts[name].ibox = box;
      this.parts[name].box = box ? this.toCanvasBox(box) : null;
    }
  }

  toCanvas(x, y) {
    return { x: x * this.sx + this.ox, y: y * this.sy + this.oy };
  }

  toCanvasBox(box) {
    const a = this.toCanvas(box[0], box[1]);
    const b = this.toCanvas(box[2], box[3]);
    return {
      x0: a.x, y0: a.y, x1: b.x, y1: b.y,
      cx: (a.x + b.x) / 2, cy: (a.y + b.y) / 2,
    };
  }

  /* ------------------------------------------------------------------ control */
  setStatus(status) {
    this.status = status;
    const map = {
      idle: 'neutral',
      listening: 'listening',
      thinking: 'thinking',
      speaking: 'speaking',
      error: 'error',
    };
    if (status !== this.emotion || this.opts.emotions) {
      this.setEmotion(map[status] || 'neutral');
    }
  }

  setEmotion(name) {
    if (!this.opts.emotions && name !== 'neutral') return;
    const preset = EMOTIONS[name] || EMOTIONS.neutral;
    this.emotion = name;
    this.emotionTarget = Object.assign({}, preset);
  }

  setLevel(value) {
    this.level = Math.max(0, Math.min(1, value));
  }

  setVolume(value) {
    this.volume = Math.max(0, Math.min(2, value));
  }

  attachTracker(tracker) {
    this.tracker = tracker;
    this.trackerEnabled = !!tracker && this.opts.eyeTracking;
  }

  setTrackerEnabled(enabled) {
    this.trackerEnabled = !!this.tracker && enabled;
  }

  /* -------------------------------------------------------------------- speech */
  pushSpeech(frames) {
    if (!frames || !frames.length) return;
    this.speech.frames = frames;
    this.speech.cursor = 0;
    this.speech.start = performance.now();
    this.speech.active = true;
    if (this.opts.animations) this.setEmotion('speaking');
  }

  clearSpeech() {
    this.speech.frames = [];
    this.speech.cursor = 0;
    this.speech.active = false;
  }

  /* -------------------------------------------------------------------- loop */
  start() {
    if (this.running) return;
    this.running = true;
    this.lastTs = performance.now();
    this.t0 = this.lastTs;
    requestAnimationFrame((ts) => this._frame(ts));
  }

  stop() {
    this.running = false;
  }

  _frame(ts) {
    if (!this.running) return;
    const dt = Math.min(0.05, Math.max(0.008, (ts - this.lastTs) / 1000));
    this.lastTs = ts;
    this.t = (ts - this.t0) / 1000;
    this.update(dt);
    this.draw();
    requestAnimationFrame((t) => this._frame(t));
  }

  update(dt) {
    if (!this.opts.animations) return;

    // ---- emotion smoothing
    const target = this.emotionTarget || EMOTIONS.neutral;
    const k = 1 - Math.pow(0.001, dt);
    const lerp = (a, b) => a + (b - a) * k;
    this.emotionState.eyeY = lerp(this.emotionState.eyeY, target.eyeY || 0);
    this.emotionState.eyeScale = lerp(this.emotionState.eyeScale, target.eyeScale || 1);
    this.emotionState.mouth = lerp(this.emotionState.mouth, target.mouth || 0.18);
    this.emotionState.tilt = lerp(this.emotionState.tilt, target.tilt || 0);
    const blinkMin = target.blink ? target.blink[0] : 3;
    const blinkMax = target.blink ? target.blink[1] : 5;
    this.emotionState.blinkMin = lerp(this.emotionState.blinkMin, blinkMin);
    this.emotionState.blinkMax = lerp(this.emotionState.blinkMax, blinkMax);

    // ---- blink
    this.blink.timer -= dt;
    if (!this.blink.active && this.blink.timer <= 0) {
      this.blink.active = true;
      this.blink.phase = 0;
      this.blink.timer = blinkMin + Math.random() * Math.max(0.1, blinkMax - blinkMin);
    }
    if (this.blink.active) {
      this.blink.phase += dt / BLINK_DURATION;
      if (this.blink.phase >= 1) this.blink.active = false;
    }
    const blinkAmount = this.blink.active
      ? 1 - Math.abs(this.blink.phase * 2 - 1)
      : 0;

    // ---- speech / mouth
    if (this.speech.active && this.speech.frames.length) {
      const elapsed = (performance.now() - this.speech.start) / 1000;
      while (this.speech.cursor < this.speech.frames.length &&
             this.speech.frames[this.speech.cursor].t <= elapsed) {
        const frame = this.speech.frames[this.speech.cursor];
        this.speech.cursor++;
        if (frame.open !== undefined) this.mouth.target = frame.open;
      }
      if (this.speech.cursor >= this.speech.frames.length) {
        this.speech.active = false;
      }
    } else {
      this.mouth.target = this.emotionState.mouth;
    }
    const provided = this.opts.getLevel ? this.opts.getLevel() : 0;
    this.level = Math.max(this.level * 0.7, Math.min(1, provided));
    const level = this.speech.active ? 0.55 + 0.45 * this.level : 0;
    const open = Math.max(0, Math.min(1.4, this.mouth.target * (0.72 + 0.38 * level)));
    const jitter = this.speech.active ? (Math.random() - 0.5) * 0.06 : 0;
    this.mouth.value += ((open + jitter) - this.mouth.value) * (1 - Math.pow(0.0008, dt));

    // ---- gaze
    let gx = 0;
    let gy = 0;
    if (this.trackerEnabled && this.trackerSignal) {
      gx = clamp(this.trackerSignal.gazeX || 0, -1, 1);
      gy = clamp((this.trackerSignal.gazeY || 0) * 0.8, -1, 1);
    } else if (this.status === 'listening') {
      gx = Math.sin(this.t * 0.7) * 0.18;
      gy = -0.35 + Math.sin(this.t * 0.4) * 0.08;
    } else if (this.status === 'speaking') {
      gx = Math.sin(this.t * 1.7) * 0.12;
      gy = -0.22 + Math.sin(this.t * 0.9) * 0.06;
    } else if (this.status === 'thinking') {
      gx = 0.35 + Math.sin(this.t * 0.35) * 0.12;
      gy = -0.5 + Math.sin(this.t * 0.5) * 0.08;
    } else if (this.opts.idle) {
      gx = Math.sin(this.t * 0.21) * 0.35;
      gy = Math.sin(this.t * 0.13 + 1.2) * 0.2;
    }
    this.gaze.tx = gx * 7;
    this.gaze.ty = gy * 5 + this.emotionState.eyeY * 0.6;
    this.gaze.x += (this.gaze.tx - this.gaze.x) * (1 - Math.pow(0.002, dt));
    this.gaze.y += (this.gaze.ty - this.gaze.y) * (1 - Math.pow(0.002, dt));

    // ---- head
    let yaw = 0;
    let pitch = 0;
    if (this.trackerEnabled && this.trackerSignal) {
      yaw = clamp(this.trackerSignal.yaw || 0, -1, 1);
      pitch = clamp((this.trackerSignal.pitch || 0) * 1.6, -1, 1);
    }
    let idleX = 0;
    let idleY = 0;
    if (this.opts.idle && this.status === 'idle') {
      idleX = Math.sin(this.t * 0.11) * 2.5;
      idleY = Math.sin(this.t * 0.09 + 2.1) * 1.6;
    } else if (this.status === 'speaking') {
      idleX = Math.sin(this.t * 2.4) * 1.4;
      idleY = Math.sin(this.t * 3.1) * 0.9;
    }
    this.head.tx = idleX + yaw * 7;
    this.head.ty = idleY + pitch * 5;
    this.head.trot = this.emotionState.tilt + yaw * 2.2 + pitch * 1.2;
    this.head.x += (this.head.tx - this.head.x) * (1 - Math.pow(0.003, dt));
    this.head.y += (this.head.ty - this.head.y) * (1 - Math.pow(0.003, dt));
    this.head.rot += (this.head.trot - this.head.rot) * (1 - Math.pow(0.004, dt));

    // ---- parts
    const mouthBox = this.parts.mouth.box;
    const mouthScale = 1 + Math.max(0, this.mouth.value - 0.18) * MOUTH_RANGE;
    for (const name of PART_ORDER) {
      const part = this.parts[name];
      const box = part.box;
      if (!box) continue;
      const isEye = name.includes('eye');
      const sy = isEye
        ? 1 - blinkAmount * 0.86
        : mouthScale;
      const sx = isEye ? 1 : 1 + Math.max(0, this.mouth.value - 0.18) * 0.12;
      const ty = isEye ? this.gaze.y : Math.sin(this.t * 6) * (this.speech.active ? 1.2 : 0.3);
      const tx = isEye ? this.gaze.x : Math.sin(this.t * 3.2) * (this.speech.active ? 1.4 : 0.4);
      part.sx += (sx - part.sx) * (1 - Math.pow(0.0009, dt));
      part.sy += (sy - part.sy) * (1 - Math.pow(0.0009, dt));
      part.tx += (tx - part.tx) * (1 - Math.pow(0.012, dt));
      part.ty += (ty - part.ty) * (1 - Math.pow(0.012, dt));
      part.rot = 0;
    }
  }

  draw() {
    const ctx = this.ctx;
    if (!this.image || !this.face) return;
    ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
    ctx.clearRect(0, 0, this.cw, this.ch);
    ctx.save();
    ctx.translate(this.cw / 2 + this.head.x, this.ch * 0.44 + this.head.y);
    ctx.rotate(this.head.rot * Math.PI / 180);
    ctx.translate(-this.cw / 2, -this.ch * 0.44);
    this.drawBase(ctx);
    for (const name of PART_ORDER) this.drawPart(ctx, name);
    ctx.restore();
    if (this.status === 'error') {
      ctx.save();
      ctx.fillStyle = 'rgba(255, 90, 110, 0.10)';
      ctx.fillRect(0, 0, this.cw, this.ch);
      ctx.restore();
    }
  }

  drawBase(ctx) {
    const w = this.face.width * this.sx;
    const h = this.face.height * this.sy;
    ctx.drawImage(this.image, this.ox, this.oy, w, h);
  }

  drawPart(ctx, name) {
    const part = this.parts[name];
    const box = part.box;
    const ibox = part.ibox;
    if (!box || !ibox) return;
    const w = box.x1 - box.x0;
    const h = box.y1 - box.y0;
    if (w <= 1 || h <= 1) return;
    ctx.save();
    ctx.beginPath();
    ctx.rect(box.x0, box.y0, w, h);
    ctx.clip();
    ctx.translate(box.cx + part.tx, box.cy + part.ty);
    ctx.scale(part.sx, part.sy);
    ctx.translate(-box.cx, -box.cy);
    ctx.drawImage(this.image, ibox[0], ibox[1], ibox[2] - ibox[0], ibox[3] - ibox[1], box.x0, box.y0, w, h);
    ctx.restore();
  }

  /* ------------------------------------------------------------- region tooling */
  getImageRegion(name) {
    return this.face && this.face.parts && this.face.parts[name]
      ? this.face.parts[name].box
      : null;
  }
}

function clamp(value, min, max) {
  return Math.max(min, Math.min(max, value));
}

export function loadImage(url) {
  return new Promise((resolve, reject) => {
    const image = new Image();
    image.onload = () => resolve(image);
    image.onerror = () => reject(new Error(`не удалось загрузить ${url}`));
    image.src = url;
  });
}
